'use strict';
window.ProductPhotos={slots:['front','back','both'],current:{},files:{},urls:[],
 open(product){this.urls.forEach(URL.revokeObjectURL);this.urls=[];this.files={};this.current={...(product?.imageViews||{front:product?.image,back:product?.images?.[1],both:product?.images?.[2]})};for(const key of this.slots){const file=document.getElementById('p-photo-'+key);file.value='';file.required=key==='front'&&!this.current.front;file.onchange=()=>{const selected=file.files[0];if(selected){if(selected.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(selected.type)){file.value='';document.getElementById('product-status').textContent='Choose a JPG, PNG or WebP under 2 MB.';return;}this.files[key]=selected;const url=URL.createObjectURL(selected);this.urls.push(url);this.preview(key,url);}else{delete this.files[key];this.preview(key,this.current[key]);}};document.getElementById('remove-photo-'+key).onclick=()=>{delete this.current[key];delete this.files[key];file.value='';file.required=key==='front';this.preview(key,null);};this.preview(key,this.current[key]);}},
 preview(key,src){const image=document.getElementById('preview-photo-'+key);image.hidden=!src;if(src)image.src=src;else image.removeAttribute('src');document.getElementById('remove-photo-'+key).hidden=!src;},
 async upload(api,notify){for(const key of this.slots){const selected=this.files[key];if(!selected)continue;notify('Uploading '+(key==='both'?'both views':key)+' photo…');const body=new FormData();body.append('image',selected);const response=await api('upload',{method:'POST',body});this.current[key]=response.url;delete this.files[key];}if(!this.current.front)throw Error('Add a front photo for this product.');return Object.fromEntries(Object.entries(this.current).filter(([,src])=>src));}
};
